// Generate a UUID without hyphens
function generateSessionId() {
  return 'xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx'.replace(/x/g, function() {
    return Math.floor(Math.random() * 16).toString(16);
  });
}

const output = [];

for (const item of $input.all()) {
  const data = item.json;

  output.push({
    json: {
      chatInput: data.chatInput || '',
      sessionId: generateSessionId(),
      row_number: data.row_number,
      expected_answer: data.expected_answer || '',
      expected_tool: data.expected_tool || '',
      expected_found: data.expected_found || ''
    }
  });
}

return output;

// Code node: Calculate RAG Metrics (Correct Precision/Recall)
const item = $input.first();
const agentOutput = item.json;
const preparedData = $('Prepare Data').first().json;

// === TOKENIZATION ===
function tokenize(text) {
  return text
    .toLowerCase()
    .replace(/[^\wа-яё\s-]/gi, ' ')
    .split(/\s+/)
    .filter(word => word.length > 0);
}

function getNgrams(tokens, n = 1) {
  const ngrams = [];
  for (let i = 0; i <= tokens.length - n; i++) {
    ngrams.push(tokens.slice(i, i + n).join(' '));
  }
  return ngrams;
}

// === CRITICAL FACTS (Exact Match) ===
function extractCriticalFacts(text) {
  const facts = [];

  // Order IDs
  const orderIds = text.match(/ORD-\d{8}-\d{4}/gi) || [];
  facts.push(...orderIds.map(id => id.toUpperCase()));

  // Tracking Numbers
  const tracking = text.match(/TRK-\d+/gi) || [];
  facts.push(...tracking.map(t => t.toUpperCase()));

  // Dates
  const dates = text.match(/\d{4}-\d{2}-\d{2}/g) || [];
  facts.push(...dates);

  return [...new Set(facts)]; // unique
}

// === PRECISION/RECALL CALCULATION ===
function calculateMetrics(expected, actual) {
  // 1. Critical facts (exact match)
  const expectedCritical = extractCriticalFacts(expected);
  const actualCritical = extractCriticalFacts(actual);

  let criticalTP = 0;
  let criticalFP = 0;
  let criticalFN = 0;

  expectedCritical.forEach(fact => {
    if (actualCritical.includes(fact)) {
      criticalTP++;
    } else {
      criticalFN++;
    }
  });

  actualCritical.forEach(fact => {
    if (!expectedCritical.includes(fact)) {
      criticalFP++;
    }
  });

  // 2. Word-level overlap (unigrams)
  const expectedTokens = tokenize(expected);
  const actualTokens = tokenize(actual);

  const expectedSet = new Set(expectedTokens);
  const actualSet = new Set(actualTokens);

  let wordTP = 0;
  let wordFP = 0;
  let wordFN = 0;

  expectedSet.forEach(word => {
    if (actualSet.has(word)) {
      wordTP++;
    } else {
      wordFN++;
    }
  });

  actualSet.forEach(word => {
    if (!expectedSet.has(word)) {
      wordFP++;
    }
  });

  // 3. Комбинированные метрики
  // Взвешиваем критичные факты выше чем обычные слова
  const totalTP = criticalTP * 3 + wordTP;
  const totalFP = criticalFP * 3 + wordFP;
  const totalFN = criticalFN * 3 + wordFN;

  return {
    tp: totalTP,
    fp: totalFP,
    fn: totalFN,
    criticalTP,
    criticalFP,
    criticalFN,
    wordTP,
    wordFP,
    wordFN
  };
}

// === ОСНОВНОЙ КОД ===
let usedTools = [];
let usedTool = 'NONE';

if (agentOutput.intermediateSteps && Array.isArray(agentOutput.intermediateSteps)) {
  usedTools = agentOutput.intermediateSteps
    .map(step => step.action?.tool)
    .filter(tool => tool);

  if (usedTools.includes('Postgres_PGVector_Store')) {
    usedTool = 'RAG';
  } else if (usedTools.includes('Query Document Rows')) {
    usedTool = 'SQL';
  } else if (usedTools.length > 0) {
    usedTool = usedTools[0];
  }
}

const answer = (agentOutput.output || '').toLowerCase();
const notFoundIndicators = [
  'не нашел', 'не найден', 'не нашла', 'не обнаружил',
  'отсутствует', 'нет информации', 'не могу найти'
];
const actualFound = notFoundIndicators.some(ind => answer.includes(ind)) ? 'No' : 'Yes';

// Расчет метрик
const metrics = calculateMetrics(
  preparedData.expected_answer,
  agentOutput.output || ''
);

// === PRECISION / RECALL ===
const precision = (metrics.tp + metrics.fp) > 0
  ? metrics.tp / (metrics.tp + metrics.fp)
  : 0;

const recall = (metrics.tp + metrics.fn) > 0
  ? metrics.tp / (metrics.tp + metrics.fn)
  : 0;

const f1Score = (precision + recall) > 0
  ? 2 * (precision * recall) / (precision + recall)
  : 0;

// Critical Facts Precision/Recall (важнее обычных слов)
const criticalPrecision = (metrics.criticalTP + metrics.criticalFP) > 0
  ? metrics.criticalTP / (metrics.criticalTP + metrics.criticalFP)
  : 1; // если нет критичных фактов - считаем что все ок

const criticalRecall = (metrics.criticalTP + metrics.criticalFN) > 0
  ? metrics.criticalTP / (metrics.criticalTP + metrics.criticalFN)
  : 1;

// === ДОПОЛНИТЕЛЬНЫЕ МЕТРИКИ ===
const toolMatch = usedTool === preparedData.expected_tool ? 1 : 0;
const foundMatch = actualFound === preparedData.expected_found ? 1 : 0;

// Overall Score
const overallScore = (
  toolMatch * 0.15 +           // 15% - правильный инструмент
  foundMatch * 0.15 +          // 15% - правильное определение наличия данных
  criticalPrecision * 0.25 +   // 25% - точность критичных фактов
  criticalRecall * 0.25 +      // 25% - полнота критичных фактов
  precision * 0.10 +           // 10% - общая точность
  recall * 0.10                // 10% - общая полнота
);

// Pass/Fail
const passFail = (
  toolMatch === 1 && 
  foundMatch === 1 && 
  criticalPrecision >= 0.9 &&  // 90%+ точность критичных фактов
  criticalRecall >= 0.8        // 80%+ полнота критичных фактов
) ? 'PASS' : 'FAIL';

// === РЕЗУЛЬТАТ ===
return [{
  json: {
    // Основные поля
    chatInput: preparedData.chatInput,
    row_number: preparedData.row_number,

    // Expected/Actual
    expected_answer: preparedData.expected_answer,
    expected_tool: preparedData.expected_tool,
    expected_found: preparedData.expected_found,
    actual_answer: agentOutput.output || '',
    actual_tool: usedTool,
    actual_found: actualFound,

    // Основные метрики
    precision: Math.round(precision * 1000) / 1000,
    recall: Math.round(recall * 1000) / 1000,
    f1_score: Math.round(f1Score * 1000) / 1000,

    // Критичные факты (ID, трек-номера, даты)
    critical_precision: Math.round(criticalPrecision * 1000) / 1000,
    critical_recall: Math.round(criticalRecall * 1000) / 1000,

    // Детали
    true_positives: metrics.tp,
    false_positives: metrics.fp,
    false_negatives: metrics.fn,
    critical_tp: metrics.criticalTP,
    critical_fp: metrics.criticalFP,
    critical_fn: metrics.criticalFN,

    // Дополнительно
    metric_tool_match: toolMatch,
    metric_found_match: foundMatch,
    overall_score: Math.round(overallScore * 1000) / 1000,
    pass_fail: passFail,

    // Диагностика
    tools_used: usedTools.join(', '),
    tool_calls_count: agentOutput.intermediateSteps?.length || 0
  }
}];
